1	// This file implements organization-scoped policy publishing, rollback,
2	// and review on top of the decision core. Each organization versions its
3	// own policy set independently; all state is in-memory and lives until
4	// the service instance ends.
5	package darksafe
6	
7	import (
8		"errors"
9		"fmt"
10		"sort"
11		"strings"
12		"sync"
13	)
14	
15	// Effect is the outcome a policy produces when it matches a request.
16	type Effect string
17	
18	const (
19		EffectAllow Effect = "allow"
20		EffectDeny  Effect = "deny"
21	)
22	
23	// Policy binds one subject and one action to a scope with an effect.
24	type Policy struct {
25		ID        string
26		Subject   string
27		Action    string
28		Scope     string
29		Effect    Effect
30		Recursive bool // false: only the exact scope; true: the scope and its descendants
31	}
32	
33	// Sentinel errors so callers can distinguish failure causes with errors.Is.
34	var (
35		// ErrVersionConflict means the caller's expected current version is stale.
36		ErrVersionConflict = errors.New("darksafe: version conflict")
37		// ErrVersionNotFound means the requested historical version does not exist.
38		ErrVersionNotFound = errors.New("darksafe: version not found")
39		// ErrInvalidPolicySet means the submitted policy set failed validation.
40		ErrInvalidPolicySet = errors.New("darksafe: invalid policy set")
41		// ErrMissingOrganization means an operation was called without an organization.
42		ErrMissingOrganization = errors.New("darksafe: organization is required")
43	)
44	
45	// OrgRequest is an access request evaluated against one organization's
46	// published policies. Both organizations must equal the decision organization.
47	type OrgRequest struct {
48		SubjectOrg  string
49		ResourceOrg string
50		Subject     Subject
51		Resource    Resource
52		Action      string
53	}
54	
55	// Store holds every organization's published policy versions. It is safe
56	// for concurrent use and keeps all state in memory.
57	type Store struct {
58		mu   sync.Mutex
59		orgs map[string]*orgState
60	}
61	
62	type orgState struct {
63		current  int            // 0 means nothing published yet
64		versions map[int][]Policy // immutable snapshots per version
65	}
66	
67	// NewStore returns an empty Store.
68	func NewStore() *Store {
69		return &Store{orgs: make(map[string]*orgState)}
70	}
71	
72	func (s *Store) orgLocked(name string) *orgState {
73		st, ok := s.orgs[name]
74		if !ok {
75			st = &orgState{versions: make(map[int][]Policy)}
76			s.orgs[name] = st
77		}
78		return st
79	}
80	
81	// CurrentVersion reports the organization's current version, 0 if it has
82	// never published.
83	func (s *Store) CurrentVersion(org string) int {
84		s.mu.Lock()
85		defer s.mu.Unlock()
86		if st, ok := s.orgs[org]; ok {
87			return st.current
88		}
89		return 0
90	}
91	
92	// Publish validates and publishes a complete policy set as the next
93	// version. expectedVersion must equal the organization's current version;
94	// on any validation or version failure nothing changes and no version
95	// number is consumed.
96	func (s *Store) Publish(org string, expectedVersion int, policies []Policy) (int, error) {
97		if org == "" {
98			return 0, ErrMissingOrganization
99		}
100		snapshot, err := validatePolicies(policies)
101		if err != nil {
102			return 0, err
103		}
104		s.mu.Lock()
105		defer s.mu.Unlock()
106		st := s.orgLocked(org)
107		if expectedVersion != st.current {
108			return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
109		}
110		st.current++
111		st.versions[st.current] = snapshot
112		return st.current, nil
113	}
114	
115	// Rollback republishes the full content of an existing historical version
116	// as a new version. History is never deleted or rewritten.
117	func (s *Store) Rollback(org string, expectedVersion, targetVersion int) (int, error) {
118		if org == "" {
119			return 0, ErrMissingOrganization
120		}
121		s.mu.Lock()
122		defer s.mu.Unlock()
123		st := s.orgLocked(org)
124		src, ok := st.versions[targetVersion]
125		if !ok {
126			return 0, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, targetVersion)
127		}
128		if expectedVersion != st.current {
129			return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
130		}
131		st.current++
132		st.versions[st.current] = append([]Policy(nil), src...)
133		return st.current, nil
134	}
135	
136	// Policies returns a copy of the full policy set of one version. Mutating
137	// the result does not affect published content.
138	func (s *Store) Policies(org string, version int) ([]Policy, error) {
139		s.mu.Lock()
140		defer s.mu.Unlock()
141		st, ok := s.orgs[org]
142		if !ok {
143			return nil, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, version)
144		}
145		src, ok := st.versions[version]
146		if !ok {
147			return nil, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, version)
148		}
149		return append([]Policy(nil), src...), nil
150	}
151	
152	// Decide evaluates a request against the organization's current version.
153	// The whole decision uses that single version's snapshot, and the version
154	// actually used is reported in Decision.Version.
155	func (s *Store) Decide(org string, req OrgRequest) Decision {
156		if d, ok := checkRequest(org, req); !ok {
157			return d
158		}
159		s.mu.Lock()
160		version := 0
161		var policies []Policy
162		if st, ok := s.orgs[org]; ok {
163			version = st.current
164			policies = append([]Policy(nil), st.versions[version]...)
165		}
166		s.mu.Unlock()
167		if version == 0 {
168			return Decision{Allowed: false, Reason: "organization has no published version"}
169		}
170		return evaluate(req, policies, version)
171	}
172	
173	// Review re-evaluates a request against a specific historical version.
174	// Later publishes or rollbacks cannot change its outcome; a version that
175	// does not exist is a denial with a reason, never a silent fallback to
176	// the current version.
177	func (s *Store) Review(org string, version int, req OrgRequest) Decision {
178		if d, ok := checkRequest(org, req); !ok {
179			return d
180		}
181		s.mu.Lock()
182		var policies []Policy
183		found := false
184		if st, ok := s.orgs[org]; ok {
185			if src, ok := st.versions[version]; ok {
186				policies = append([]Policy(nil), src...)
187				found = true
188			}
189		}
190		s.mu.Unlock()
191		if !found {
192			return Decision{Allowed: false, Reason: fmt.Sprintf("version %d not found", version)}
193		}
194		return evaluate(req, policies, version)
195	}
196	
197	// checkRequest validates the request envelope. Every failure is a denial
198	// with a distinguishable reason.
199	func checkRequest(org string, req OrgRequest) (Decision, bool) {
200		switch {
201		case org == "":
202			return Decision{Allowed: false, Reason: "missing decision organization"}, false
203		case req.SubjectOrg == "":
204			return Decision{Allowed: false, Reason: "missing subject organization"}, false
205		case req.ResourceOrg == "":
206			return Decision{Allowed: false, Reason: "missing resource organization"}, false
207		case req.Subject.ID == "":
208			return Decision{Allowed: false, Reason: "missing subject id"}, false
209		case req.Resource.ID == "":
210			return Decision{Allowed: false, Reason: "missing resource id"}, false
211		case req.Action == "":
212			return Decision{Allowed: false, Reason: "missing action"}, false
213		}
214		if req.SubjectOrg != org || req.ResourceOrg != org {
215			return Decision{Allowed: false, Reason: "organization mismatch"}, false
216		}
217		if err := validateScope(req.Resource.Scope); err != nil {
218			return Decision{Allowed: false, Reason: "invalid scope: " + err.Error()}, false
219		}
220		if req.Subject.Disabled {
221			return Decision{Allowed: false, Reason: "subject is disabled"}, false
222		}
223		return Decision{}, true
224	}
225	
226	// evaluate applies one version's policies to a request. Subject roles are
227	// deliberately ignored: only the selected version's policies decide.
228	func evaluate(req OrgRequest, policies []Policy, version int) Decision {
229		seen := make(map[string]struct{})
230		denied := false
231		allowed := false
232		for _, p := range policies {
233			if p.Subject != req.Subject.ID || p.Action != req.Action {
234				continue
235			}
236			if !scopeMatches(p, req.Resource.Scope) {
237				continue
238			}
239			seen[p.ID] = struct{}{}
240			switch p.Effect {
241			case EffectDeny:
242				denied = true
243			case EffectAllow:
244				allowed = true
245			}
246		}
247		matched := make([]string, 0, len(seen))
248		for id := range seen {
249			matched = append(matched, id)
250		}
251		sort.Strings(matched)
252		switch {
253		case denied:
254			return Decision{Allowed: false, Reason: "matched deny policy", Matched: matched, Version: version}
255		case allowed:
256			return Decision{Allowed: true, Reason: "matched allow policy", Matched: matched, Version: version}
257		default:
258			return Decision{Allowed: false, Reason: "no matching allow policy", Matched: matched, Version: version}
259		}
260	}
261	
262	// scopeMatches reports whether a policy's scope covers the request scope.
263	// Matching is by slash-separated segments, so "org/a" never covers "org/ab".
264	func scopeMatches(p Policy, scope string) bool {
265		if p.Scope == scope {
266			return true
267		}
268		return p.Recursive && strings.HasPrefix(scope, p.Scope+"/")
269	}
270	
271	// validatePolicies checks a submitted policy set and returns a detached
272	// copy, so later caller mutations cannot affect published content.
273	func validatePolicies(policies []Policy) ([]Policy, error) {
274		seen := make(map[string]struct{}, len(policies))
275		out := make([]Policy, len(policies))
276		for i, p := range policies {
277			if p.ID == "" {
278				return nil, fmt.Errorf("%w: policy at index %d has an empty id", ErrInvalidPolicySet, i)
279			}
280			if _, dup := seen[p.ID]; dup {
281				return nil, fmt.Errorf("%w: duplicate policy id %q", ErrInvalidPolicySet, p.ID)
282			}
283			seen[p.ID] = struct{}{}
284			if p.Subject == "" {
285				return nil, fmt.Errorf("%w: policy %q is missing a subject", ErrInvalidPolicySet, p.ID)
286			}
287			if p.Action == "" {
288				return nil, fmt.Errorf("%w: policy %q is missing an action", ErrInvalidPolicySet, p.ID)
289			}
290			if p.Effect != EffectAllow && p.Effect != EffectDeny {
291				return nil, fmt.Errorf("%w: policy %q has unknown effect %q", ErrInvalidPolicySet, p.ID, p.Effect)
292			}
293			if err := validateScope(p.Scope); err != nil {
294				return nil, fmt.Errorf("%w: policy %q has invalid scope: %v", ErrInvalidPolicySet, p.ID, err)
295			}
296			out[i] = p
297		}
298		return out, nil
299	}
300	
301	// validateScope rejects empty paths, leading/trailing slashes, consecutive
302	// slashes, and "." or ".." segments.
303	func validateScope(scope string) error {
304		if scope == "" {
305			return errors.New("scope is empty")
306		}
307		if strings.HasPrefix(scope, "/") || strings.HasSuffix(scope, "/") {
308			return fmt.Errorf("scope %q has a leading or trailing slash", scope)
309		}
310		for _, seg := range strings.Split(scope, "/") {
311			if seg == "" {
312				return fmt.Errorf("scope %q contains consecutive slashes", scope)
313			}
314			if seg == "." || seg == ".." {
315				return fmt.Errorf("scope %q contains invalid segment %q", scope, seg)
316			}
317		}
318		return nil
319	}
